\sqrt(yB^2+xA^2);
tAB: [-xA, yB];
nAB: [yB, xA];
pA: [xA, 0];
pB: [0, yB];
alphaDeg: float(atan(yB/xA)*180/%pi);
/* Gitterweite a: A, B und die Stufe liegen auf dem Gitter (Stufenhoehe 2a, A im Abstand 3a).
   Balken (Quader) als Polygon: Laenge b = 1.4*|tAB|, Dicke h = 0.2*|nAB|; die Ecke unten
   rechts liegt in A. Schwerpunkt S in der Mitte. b und h sind in der Aufgabe Symbole. */
p1: pA + 1.4*tAB;
p2: pA + 1.4*tAB + 0.2*nAB;
p3: pA + 0.2*nAB;
pS: pA + 0.7*tAB + 0.1*nAB;
/* Momentenbilanz: Lage von B und S relativ zu A, in a (Gitter), b, h und alpha
   (et laengs des Balkens von A nach B, en senkrecht dazu nach oben rechts) */
et: [-cos(alpha), sin(alpha)];
en: [sin(alpha), cos(alpha)];
rB: (pB - pA)*a;
rS: b/2*et + h/2*en;
rSmat: matrix([rS[1]],[rS[2]]);
cross2(u, v):= u[1]*v[2] - u[2]*v[1];
/* Moment um den Gitterpunkt P (Fadenkreuz, in Gittereinheiten); sR: Richtungssinn von R_B
   (+1 zur Kante hin) */
moment_ref(P, sR):= block([r0: (P - pA)*a],
  cross2(-r0, [0, N_A]) + cross2(rB - r0, N_B*en) + cross2(rB - r0, sR*R_B*et) + cross2(rS - r0, [0, -G]));
/* Vergleich: alpha wird durch den Winkel der Skizze ersetzt, damit sin(alpha) und 2/sqrt(13)
   gleichwertig sind; beide Drehsinne bzw. Vorzeichen der Summe sind zulaessig */
same_eq(u, v):= block([d: subst(alpha = atan(yB/xA), [u - v, u + v])],
  is(ratsimp(trigsimp(d[1])) = 0) or is(ratsimp(trigsimp(d[2])) = 0));
/* Vorzeichen: Kraefte in positiver x- bzw. y-Richtung und Momente gegen den Uhrzeigersinn
   positiv (Standard der Lehrveranstaltung) */
same_sign(u, v):= is(ratsimp(trigsimp(subst(alpha = atan(yB/xA), u - v))) = 0);

